namespace svg;

internal class SvgSimplifyPiece
{
    internal System.Collections.Generic.List<SvgPoint> Source; internal System.Collections.Generic.List<SvgPoint>? Output; internal bool Closed; internal bool Drawable;
    internal SvgSimplifyPiece(SvgPoint start) { Source = new System.Collections.Generic.List<SvgPoint>(); Source.Add(new SvgPoint(start.X, start.Y)); Output = null; Closed = false; Drawable = false; }
}

internal class SvgSimplifyInterval
{
    internal int Start; internal int End;
    internal SvgSimplifyInterval(int start, int end) { Start = start; End = end; }
}

internal class SvgPathSimplifyState
{
    SvgPathData? path; SvgPathSimplifyOptions options; System.Collections.Generic.List<SvgSimplifyPiece> pieces; SvgSimplifyPiece? current; int pointCount; int curves; int rounded; int operations; double measured; bool operationExceeded;
    internal SvgPathSimplifyState(SvgPathData? normalizedPath, SvgPathSimplifyOptions simplifyOptions) { path = normalizedPath; options = simplifyOptions; pieces = new System.Collections.Generic.List<SvgSimplifyPiece>(); current = null; pointCount = 0; curves = 0; rounded = 0; operations = 0; measured = 0; operationExceeded = false; }
    internal SvgPathSimplifyResult Run()
    {
        SvgPathSimplifyError built = BuildPieces(); if (built != SvgPathSimplifyError.None) return new SvgPathSimplifier().Failure(built, null); int index = 0; while (index < pieces.Count) { SvgPathSimplifyError reduced = Reduce(pieces[index]); if (reduced != SvgPathSimplifyError.None) return new SvgPathSimplifier().Failure(reduced, Report(0)); index = index + 1; }
        SvgPathSimplifyError measuredError = Measure(); SvgPathLossyReport report = Report(measured + (curves == 0 ? 0 : options.Tolerance / 4)); if (measuredError != SvgPathSimplifyError.None) return new SvgPathSimplifier().Failure(measuredError, report); if (report.MaximumErrorBound > options.Tolerance) return new SvgPathSimplifier().Failure(SvgPathSimplifyError.ErrorLimitExceeded, report);
        SvgGeneratedPathBuilder builder = new SvgGeneratedPathBuilder(); index = 0; while (index < pieces.Count) { AddPiece(builder, pieces[index]); index = index + 1; } SvgPathData output = builder.Build(); if (output.Commands.Count > options.MaximumCommands) return new SvgPathSimplifier().Failure(SvgPathSimplifyError.CommandLimitExceeded, report); return new SvgPathSimplifyResult(true, SvgPathSimplifyError.None, output, report);
    }
    SvgPathSimplifyError BuildPieces()
    {
        int index = 0; while (index < (path ?? throw new System.InvalidOperationException("A required SVG value is unavailable.")).Commands.Count) { SvgPathCommand command = path.Commands[index]; if (command.Kind == SvgPathCommandKind.MoveTo) { if (!Start(new SvgPoint(command.EndX, command.EndY))) return SvgPathSimplifyError.PointLimitExceeded; } else { if (current == null && !Start(new SvgPoint(command.StartX, command.StartY))) return SvgPathSimplifyError.PointLimitExceeded; SvgPathSimplifyError added = Add(command); if (added != SvgPathSimplifyError.None) return added; if (command.Kind == SvgPathCommandKind.ClosePath) { (current ?? throw new System.InvalidOperationException("A required SVG value is unavailable.")).Closed = true; current = null; } } index = index + 1; } return SvgPathSimplifyError.None;
    }
    bool Start(SvgPoint point) { if (pointCount >= options.MaximumPoints) return false; current = new SvgSimplifyPiece(point); pieces.Add(current); pointCount = pointCount + 1; return true; }
    SvgPathSimplifyError Add(SvgPathCommand command)
    {
        SvgFlattenOptions flattenOptions = new SvgFlattenOptions(); flattenOptions.Tolerance = options.Tolerance / 4; flattenOptions.MaximumSubdivisionDepth = options.MaximumSubdivisionDepth; flattenOptions.MaximumSegments = options.MaximumPoints - pointCount > 0 ? options.MaximumPoints - pointCount : 1; SvgPoint start = new SvgPoint(command.StartX, command.StartY); SvgPoint end = new SvgPoint(command.EndX, command.EndY); SvgFlattenResult flat;
        if (command.Kind == SvgPathCommandKind.LineTo || command.Kind == SvgPathCommandKind.ClosePath) flat = new SvgLineSegment(start, end).Flatten(flattenOptions); else if (command.Kind == SvgPathCommandKind.QuadraticCurveTo) { flat = new SvgQuadraticBezier(start, new SvgPoint(command.Values[0], command.Values[1]), end).Flatten(flattenOptions); curves = curves + 1; } else if (command.Kind == SvgPathCommandKind.CubicCurveTo) { flat = new SvgCubicBezier(start, new SvgPoint(command.Values[0], command.Values[1]), new SvgPoint(command.Values[2], command.Values[3]), end).Flatten(flattenOptions); curves = curves + 1; } else if (command.Kind == SvgPathCommandKind.ArcTo) { SvgArcOperationResult arc = new SvgArcGeometry().FromCommand(command); if (!arc.Success) return SvgPathSimplifyError.NonFiniteResult; flat = (arc.Arc ?? throw new System.InvalidOperationException("A required SVG value is unavailable.")).Flatten(flattenOptions); if (!arc.Arc.IsLine && !arc.Arc.IsPoint) curves = curves + 1; } else return SvgPathSimplifyError.InvalidPath;
        if (!flat.Success) return Map(flat.Error); int index = 1; while (index < (flat.Points ?? throw new System.InvalidOperationException("A required SVG value is unavailable.")).Count) { if (pointCount >= options.MaximumPoints) return SvgPathSimplifyError.PointLimitExceeded; (current ?? throw new System.InvalidOperationException("A required SVG value is unavailable.")).Source.Add(new SvgPoint(flat.Points[index].Point.X, flat.Points[index].Point.Y)); pointCount = pointCount + 1; current.Drawable = true; index = index + 1; } return SvgPathSimplifyError.None;
    }
    SvgPathSimplifyError Reduce(SvgSimplifyPiece piece)
    {
        bool[] keep = new bool[piece.Source.Count]; if (piece.Source.Count == 1) keep[0] = true; else if (piece.Closed && piece.Source.Count > 2) { int anchor = Anchor(piece.Source); keep[0] = true; keep[piece.Source.Count - 1] = true; keep[anchor] = true; SvgPathSimplifyError first = ReduceRange(piece.Source, keep, 0, anchor); if (first != SvgPathSimplifyError.None) return first; SvgPathSimplifyError second = ReduceRange(piece.Source, keep, anchor, piece.Source.Count - 1); if (second != SvgPathSimplifyError.None) return second; } else { keep[0] = true; keep[piece.Source.Count - 1] = true; SvgPathSimplifyError error = ReduceRange(piece.Source, keep, 0, piece.Source.Count - 1); if (error != SvgPathSimplifyError.None) return error; }
        piece.Output = new System.Collections.Generic.List<SvgPoint>(); int index = 0; while (index < piece.Source.Count) { if (keep[index]) { SvgPoint? roundedPoint = Rounded(piece.Source[index]); if (roundedPoint == null) return SvgPathSimplifyError.NonFiniteResult; if (piece.Output.Count == 0 || !Same(piece.Output[piece.Output.Count - 1], roundedPoint)) piece.Output.Add(roundedPoint); } index = index + 1; } if (piece.Closed && piece.Output.Count > 1) piece.Output[piece.Output.Count - 1] = new SvgPoint(piece.Output[0].X, piece.Output[0].Y); return SvgPathSimplifyError.None;
    }
    SvgPathSimplifyError ReduceRange(System.Collections.Generic.List<SvgPoint> points, bool[] keep, int start, int end)
    {
        if (end <= start + 1) return SvgPathSimplifyError.None; System.Collections.Generic.Stack<SvgSimplifyInterval> stack = new System.Collections.Generic.Stack<SvgSimplifyInterval>(); stack.Push(new SvgSimplifyInterval(start, end)); while (stack.Count != 0) { SvgSimplifyInterval interval = stack.Pop(); double farthest = -1; int farthestIndex = -1; int index = interval.Start + 1; while (index < interval.End) { SvgFiniteResult distance = Distance(points[index], points[interval.Start], points[interval.End]); if (!distance.Success) return operationExceeded ? SvgPathSimplifyError.OperationLimitExceeded : SvgPathSimplifyError.NonFiniteResult; if (distance.Value > farthest) { farthest = distance.Value; farthestIndex = index; } index = index + 1; } if (farthest > options.Tolerance / 2 && farthestIndex > interval.Start) { keep[farthestIndex] = true; stack.Push(new SvgSimplifyInterval(farthestIndex, interval.End)); stack.Push(new SvgSimplifyInterval(interval.Start, farthestIndex)); } } return SvgPathSimplifyError.None;
    }
    SvgPathSimplifyError Measure()
    {
        int pieceIndex = 0; while (pieceIndex < pieces.Count) { SvgSimplifyPiece piece = pieces[pieceIndex]; int sourceIndex = 0; while (sourceIndex < piece.Source.Count) { double nearest = double.PositiveInfinity; if ((piece.Output ?? throw new System.InvalidOperationException("A required SVG value is unavailable.")).Count == 1) { SvgFiniteResult pointDistance = Distance(piece.Source[sourceIndex], piece.Output[0], piece.Output[0]); if (!pointDistance.Success) return operationExceeded ? SvgPathSimplifyError.OperationLimitExceeded : SvgPathSimplifyError.NonFiniteResult; nearest = pointDistance.Value; } else { int outputIndex = 1; while (outputIndex < piece.Output.Count) { SvgFiniteResult distance = Distance(piece.Source[sourceIndex], piece.Output[outputIndex - 1], piece.Output[outputIndex]); if (!distance.Success) return operationExceeded ? SvgPathSimplifyError.OperationLimitExceeded : SvgPathSimplifyError.NonFiniteResult; if (distance.Value < nearest) nearest = distance.Value; outputIndex = outputIndex + 1; } } if (nearest > measured) measured = nearest; sourceIndex = sourceIndex + 1; } pieceIndex = pieceIndex + 1; } return SvgPathSimplifyError.None;
    }
    SvgFiniteResult Distance(SvgPoint point, SvgPoint start, SvgPoint end)
    {
        if (operations >= options.MaximumOperations) { operationExceeded = true; return new SvgFiniteResult(false, 0, "Operation limit exceeded."); } operations = operations + 1; double scale = Scale(point, start, end); double px = point.X / scale; double py = point.Y / scale; double sx = start.X / scale; double sy = start.Y / scale; double ex = end.X / scale; double ey = end.Y / scale; double dx = ex - sx; double dy = ey - sy; double squared = dx * dx + dy * dy; double amount = squared == 0 ? 0 : ((px - sx) * dx + (py - sy) * dy) / squared; if (amount < 0) amount = 0; else if (amount > 1) amount = 1; double distance = SvgPlanarMath.Hypotenuse(px - (sx + amount * dx), py - (sy + amount * dy)) * scale; return SvgFiniteMath.IsFinite(distance) ? new SvgFiniteResult(true, distance, "") : new SvgFiniteResult(false, 0, "Distance is not finite.");
    }
    SvgPoint? Rounded(SvgPoint point) { double x = System.Math.Round(point.X, options.DecimalPlaces, System.MidpointRounding.ToEven); double y = System.Math.Round(point.Y, options.DecimalPlaces, System.MidpointRounding.ToEven); if (!SvgFiniteMath.IsFinite(x) || !SvgFiniteMath.IsFinite(y)) return null; x = SvgFiniteMath.NormalizeZero(x); y = SvgFiniteMath.NormalizeZero(y); if (x != point.X) rounded = rounded + 1; if (y != point.Y) rounded = rounded + 1; return new SvgPoint(x, y); }
    SvgPathLossyReport Report(double maximum) { int outputPoints = 0; int index = 0; while (index < pieces.Count) { if (pieces[index].Output != null) outputPoints = outputPoints + (pieces[index].Output ?? throw new System.InvalidOperationException("A required SVG value is unavailable.")).Count; index = index + 1; } int removed = pointCount - outputPoints; double curveBound = curves == 0 ? 0 : options.Tolerance / 4; return new SvgPathLossyReport(curves != 0 || removed != 0 || rounded != 0, curves, pointCount, outputPoints, removed, rounded, measured, curveBound, maximum, options.Tolerance); }
    int Anchor(System.Collections.Generic.List<SvgPoint> points) { int selected = 1; double farthest = -1; int index = 1; while (index + 1 < points.Count) { double distance = SvgPlanarMath.Distance(points[0], points[index]); if (distance > farthest) { farthest = distance; selected = index; } index = index + 1; } return selected; }
    static void AddPiece(SvgGeneratedPathBuilder builder, SvgSimplifyPiece piece) { if (piece.Output == null || piece.Output.Count == 0) return; builder.MoveTo(piece.Output[0].X, piece.Output[0].Y); int index = 1; int end = piece.Closed ? piece.Output.Count - 1 : piece.Output.Count; while (index < end) { builder.LineTo(piece.Output[index].X, piece.Output[index].Y); index = index + 1; } if (piece.Closed && piece.Drawable) builder.Close(); }
    static SvgPathSimplifyError Map(SvgFlattenError error) { if (error == SvgFlattenError.SegmentLimitExceeded) return SvgPathSimplifyError.PointLimitExceeded; if (error == SvgFlattenError.SubdivisionLimitExceeded) return SvgPathSimplifyError.SubdivisionLimitExceeded; if (error == SvgFlattenError.InvalidArgument) return SvgPathSimplifyError.InvalidArgument; return SvgPathSimplifyError.NonFiniteResult; }
    static double Scale(SvgPoint point, SvgPoint start, SvgPoint end) { double scale = Higher(System.Math.Abs(point.X), System.Math.Abs(point.Y)); scale = Higher(scale, System.Math.Abs(start.X)); scale = Higher(scale, System.Math.Abs(start.Y)); scale = Higher(scale, System.Math.Abs(end.X)); scale = Higher(scale, System.Math.Abs(end.Y)); return scale == 0 ? 1 : scale; }
    static double Higher(double first, double second) { return first > second ? first : second; }
    static bool Same(SvgPoint first, SvgPoint second) { return first.X == second.X && first.Y == second.Y; }
}
